/*jshint esversion: 6 */

const Sequelize = require('sequelize');
const sequelize = new Sequelize({
  database: "thunder",
  dialect: "sqlite",
  storage: "./test.sqlite"
});

const company = sequelize.define("company", {
  name: {
    type: Sequelize.STRING(255),
    defaultValue: "ACME Co"
  }},
  {}
);
const user = sequelize.define("user", {
  name: {
    type: Sequelize.STRING(255),
    defaultValue: "me"
  }},
  {}
);

user.belongsTo(company, {as: "employer"});
company.hasOne(user, {as: "employee"});

sequelize.sync({force: true}).then(() => {
  company.create({name: "ACME Co"})
    .then((company1) => {
      myCompany = company1;
      return user.create({name: "Me", employerId: myCompany.id});
    })
    .then((u) => {
      const userInst = user.findOne({
        where: {
          employerId: myCompany.id
        },
        include: [{model: company, as: "employer"}]
      })
        .then((u) => {
          console.log(JSON.stringify(u));
        });
      return userInst;
    });
});

